  1→"use client";
  2→
  3→import { useCallback, useEffect, useState } from "react";
  4→import { Play, Volume2, VolumeX, X } from "lucide-react";
  5→import { Button } from "@/components/ui/button";
  6→import {
  7→  SFX_CATEGORIES,
  8→  getSfxSettings,
  9→  setSfxSettings,
 10→  sfxPreview,
 11→  type SfxSettings,
 12→  type SfxCategoryKey,
 13→} from "@/lib/sfx";
 14→import { Tip } from "@/components/ui/tip";
 15→import { cn } from "@/lib/utils";
 16→
 17→export function SfxSettings({ open, onClose }: { open: boolean; onClose: () => void }) {
 18→  const [settings, setSettings] = useState<SfxSettings>(getSfxSettings);
 19→
 20→  // Sync from module on open
 21→  useEffect(() => {
 22→    if (open) setSettings(getSfxSettings());
 23→  }, [open]);
 24→
 25→  const update = useCallback((next: SfxSettings) => {
 26→    setSettings(next);
 27→    setSfxSettings(next);
 28→  }, []);
 29→
 30→  const setMaster = useCallback((v: number) => {
 31→    update({ ...settings, master: v });
 32→  }, [settings, update]);
 33→
 34→  const toggleMute = useCallback(() => {
 35→    update({ ...settings, muted: !settings.muted });
 36→  }, [settings, update]);
 37→
 38→  const setCatVolume = useCallback((key: SfxCategoryKey, v: number) => {
 39→    update({
 40→      ...settings,
 41→      categories: {
 42→        ...settings.categories,
 43→        [key]: { ...settings.categories[key], volume: v },
 44→      },
 45→    });
 46→  }, [settings, update]);
 47→
 48→  const toggleCat = useCallback((key: SfxCategoryKey) => {
 49→    update({
 50→      ...settings,
 51→      categories: {
 52→        ...settings.categories,
 53→        [key]: { ...settings.categories[key], enabled: !settings.categories[key].enabled },
 54→      },
 55→    });
 56→  }, [settings, update]);
 57→
 58→  useEffect(() => {
 59→    if (!open) return;
 60→    const onKeyDown = (e: KeyboardEvent) => {
 61→      if (e.key === "Escape") onClose();
 62→    };
 63→    window.addEventListener("keydown", onKeyDown);
 64→    return () => window.removeEventListener("keydown", onKeyDown);
 65→  }, [open, onClose]);
 66→
 67→  if (!open) return null;
 68→
 69→  return (
 70→    <div
 71→      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
 72→      onClick={onClose}
 73→    >
 74→      <div
 75→        className="w-full max-w-md rounded-lg border bg-background shadow-lg flex flex-col max-h-[80vh]"
 76→        onClick={(e) => e.stopPropagation()}
 77→      >
 78→        {/* Header */}
 79→        <div className="flex items-center justify-between border-b px-4 py-3">
 80→          <h2 className="text-sm font-semibold flex items-center gap-2">
 81→            <Volume2 className="size-4" />
 82→            Sound Effects
 83→          </h2>
 84→          <button
 85→            onClick={onClose}
 86→            className="rounded p-1 transition-colors hover:bg-muted/50"
 87→          >
 88→            <X className="size-4" />
 89→          </button>
 90→        </div>
 91→
 92→        {/* Content */}
 93→        <div className="flex-1 overflow-y-auto min-h-0 px-4 py-3 space-y-4">
 94→          {/* Master volume */}
 95→          <div className="flex items-center gap-3">
 96→            <span className="text-xs text-muted-foreground w-20 shrink-0">Master</span>
 97→            <input
 98→              type="range"
 99→              min={0}
100→              max={100}
101→              value={Math.round(settings.master * 100)}
102→              onChange={(e) => setMaster(Number(e.target.value) / 100)}
103→              className="flex-1 h-1.5 accent-primary cursor-pointer"
104→            />
105→            <span className="text-xs text-muted-foreground w-8 text-right tabular-nums">
106→              {Math.round(settings.master * 100)}
107→            </span>
108→            <Button
109→              variant={settings.muted ? "destructive" : "ghost"}
110→              size="icon-xs"
111→              onClick={toggleMute}
112→              title={settings.muted ? "Unmute all" : "Mute all"}
113→            >
114→              {settings.muted ? <VolumeX className="size-3.5" /> : <Volume2 className="size-3.5" />}
115→            </Button>
116→          </div>
117→
118→          {/* Divider */}
119→          <div className="border-t" />
120→
121→          {/* Category rows */}
122→          <div className="space-y-2.5">
123→            {SFX_CATEGORIES.map((cat) => {
124→              const catSettings = settings.categories[cat.key];
125→              const disabled = settings.muted || !catSettings.enabled;
126→              return (
127→                <div key={cat.key} className={cn("space-y-1", disabled && "opacity-40")}>
128→                  {/* Row 1: label + controls */}
129→                  <div className="flex items-center gap-2">
130→                    {/* Color dot */}
131→                    <span className={cn("size-2 rounded-full shrink-0", cat.color)} />
132→                    {/* Label */}
133→                    <Tip text={cat.label}><span className="text-xs font-medium flex-1 truncate">{cat.label}</span></Tip>
134→                    {/* Preview */}
135→                    <button
136→                      onClick={() => sfxPreview(cat.key)}
137→                      className="rounded p-1 transition-colors hover:bg-muted/50"
138→                      title="Preview sound"
139→                    >
140→                      <Play className="size-3" />
141→                    </button>
142→                    {/* Toggle */}
143→                    <button
144→                      onClick={() => toggleCat(cat.key)}
145→                      className={cn(
146→                        "size-4 rounded border transition-colors flex items-center justify-center",
147→                        catSettings.enabled
148→                          ? "bg-primary border-primary text-primary-foreground"
149→                          : "border-muted-foreground/30"
150→                      )}
151→                      title={catSettings.enabled ? "Disable" : "Enable"}
152→                    >
153→                      {catSettings.enabled && (
154→                        <svg viewBox="0 0 12 12" className="size-2.5" fill="none" stroke="currentColor" strokeWidth={2}>
155→                          <path d="M2 6l3 3 5-5" />
156→                        </svg>
157→                      )}
158→                    </button>
159→                  </div>
160→                  {/* Row 2: description + volume */}
161→                  <div className="flex items-center gap-2 pl-4">
162→                    <Tip text={cat.description}><span className="text-[10px] text-muted-foreground flex-1 truncate">
163→                      {cat.description}
164→                    </span></Tip>
165→                    <input
166→                      type="range"
167→                      min={0}
168→                      max={100}
169→                      value={Math.round(catSettings.volume * 100)}
170→                      onChange={(e) => setCatVolume(cat.key, Number(e.target.value) / 100)}
171→                      className="w-20 h-1 accent-primary cursor-pointer"
172→                    />
173→                    <span className="text-[10px] text-muted-foreground w-6 text-right tabular-nums">
174→                      {Math.round(catSettings.volume * 100)}
175→                    </span>
176→                  </div>
177→                </div>
178→              );
179→            })}
180→          </div>
181→        </div>
182→
183→        {/* Footer */}
184→        <div className="border-t px-4 py-2.5 flex items-center justify-between">
185→          <span className="text-[10px] text-muted-foreground">
186→            Sounds by Kenney (CC0) via soundcn
187→          </span>
188→          <Button variant="ghost" size="xs" onClick={onClose}>
189→            Done
190→          </Button>
191→        </div>
192→      </div>
193→    </div>
194→  );
195→}
