  1→"use client";
  2→
  3→/**
  4→ * Notification inbox dropdown. Shows a list of notification items from agent
  5→ * events (done, error, control requests, questions). Each item is clickable
  6→ * to navigate to the associated agent.
  7→ */
  8→
  9→import { useEffect, useRef, useState } from "react";
 10→import { AlertTriangle, Bell, BellOff, CheckCircle2, HelpCircle, Trash2, XCircle } from "lucide-react";
 11→import { sendTestNotification } from "@/lib/notifications";
 12→import { cn } from "@/lib/utils";
 13→import type { NotificationItem, NotificationType } from "@/lib/types";
 14→
 15→const TYPE_CONFIG: Record<NotificationType, { icon: typeof CheckCircle2; color: string }> = {
 16→  done: { icon: CheckCircle2, color: "text-green-500" },
 17→  error: { icon: XCircle, color: "text-red-500" },
 18→  control_request: { icon: AlertTriangle, color: "text-yellow-500" },
 19→  question: { icon: HelpCircle, color: "text-blue-400" },
 20→};
 21→
 22→function relativeTime(ts: number): string {
 23→  const diff = Date.now() - ts;
 24→  if (diff < 60_000) return "just now";
 25→  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
 26→  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
 27→  return `${Math.floor(diff / 86_400_000)}d ago`;
 28→}
 29→
 30→export function NotificationInbox({
 31→  notifications,
 32→  enabled,
 33→  onToggleEnabled,
 34→  onSelect,
 35→  onDismiss,
 36→  onClear,
 37→  onClose,
 38→  onTestPush,
 39→}: {
 40→  notifications: NotificationItem[];
 41→  enabled: boolean;
 42→  onToggleEnabled: () => void;
 43→  onSelect: (agentId: string, notificationId: string) => void;
 44→  onDismiss: (id: string) => void;
 45→  onClear: () => void;
 46→  onClose: () => void;
 47→  onTestPush?: () => void;
 48→}) {
 49→  const ref = useRef<HTMLDivElement>(null);
 50→  const [testResult, setTestResult] = useState<string | null>(null);
 51→
 52→  // Close on click-outside or Escape
 53→  useEffect(() => {
 54→    function handleClick(e: MouseEvent) {
 55→      if (ref.current && !ref.current.contains(e.target as Node)) {
 56→        onClose();
 57→      }
 58→    }
 59→    function handleKey(e: KeyboardEvent) {
 60→      if (e.key === "Escape") onClose();
 61→    }
 62→    document.addEventListener("mousedown", handleClick);
 63→    document.addEventListener("keydown", handleKey);
 64→    return () => {
 65→      document.removeEventListener("mousedown", handleClick);
 66→      document.removeEventListener("keydown", handleKey);
 67→    };
 68→  }, [onClose]);
 69→
 70→  return (
 71→    <div
 72→      ref={ref}
 73→      className="absolute right-0 top-full z-50 mt-1 w-80 max-h-[400px] rounded-md border bg-popover shadow-md flex flex-col"
 74→    >
 75→      {/* Header */}
 76→      <div className="flex items-center justify-between border-b px-3 py-2">
 77→        <div className="flex items-center gap-2">
 78→          <span className="text-xs font-medium">Notifications</span>
 79→          <button
 80→            onClick={onToggleEnabled}
 81→            className={cn(
 82→              "flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] transition-colors",
 83→              enabled
 84→                ? "bg-primary/15 text-primary"
 85→                : "bg-muted text-muted-foreground hover:text-foreground"
 86→            )}
 87→            title={enabled ? "Disable desktop notifications" : "Enable desktop notifications"}
 88→          >
 89→            {enabled ? <Bell className="size-2.5" /> : <BellOff className="size-2.5" />}
 90→            {enabled ? "on" : "off"}
 91→          </button>
 92→        </div>
 93→        <div className="flex items-center gap-2">
 94→          {enabled && (
 95→            <button
 96→              onClick={() => {
 97→                const result = sendTestNotification();
 98→                setTestResult(result);
 99→                onTestPush?.();
100→                if (result === "sent") setTimeout(() => setTestResult(null), 3000);
101→              }}
102→              className="text-[10px] text-muted-foreground hover:text-foreground transition-colors"
103→            >
104→              Test
105→            </button>
106→          )}
107→          {notifications.length > 0 && (
108→            <button
109→              onClick={onClear}
110→              className="text-[10px] text-muted-foreground hover:text-foreground transition-colors"
111→            >
112→              Clear all
113→            </button>
114→          )}
115→        </div>
116→      </div>
117→
118→      {/* Test result diagnostic */}
119→      {testResult && (
120→        <div className={cn(
121→          "border-b px-3 py-1.5 text-[10px]",
122→          testResult === "sent" ? "text-green-400 bg-green-500/5" : "text-red-400 bg-red-500/5"
123→        )}>
124→          {testResult}
125→        </div>
126→      )}
127→
128→      {/* Items */}
129→      <div className="flex-1 overflow-y-auto">
130→        {notifications.length === 0 ? (
131→          <div className="flex items-center justify-center py-8 text-xs text-muted-foreground">
132→            No notifications
133→          </div>
134→        ) : (
135→          notifications.map((item) => {
136→            const config = TYPE_CONFIG[item.type];
137→            const Icon = config.icon;
138→            return (
139→              <div
140→                key={item.id}
141→                className={cn(
142→                  "group flex items-start gap-2.5 px-3 py-2.5 transition-colors hover:bg-muted/50 cursor-pointer border-b border-border/50 last:border-b-0",
143→                  !item.read && "bg-muted/20"
144→                )}
145→                onClick={() => onSelect(item.agentId, item.id)}
146→              >
147→                <Icon className={cn("size-3.5 mt-0.5 shrink-0", config.color)} />
148→                <div className="min-w-0 flex-1">
149→                  <div className="text-xs leading-tight">{item.message}</div>
150→                  <div className="mt-0.5 flex items-center gap-2 text-[10px] text-muted-foreground">
151→                    <span className="truncate max-w-[140px]">{item.agentLabel}</span>
152→                    <span>{relativeTime(item.timestamp)}</span>
153→                  </div>
154→                </div>
155→                {!item.read && (
156→                  <span className="mt-1.5 size-1.5 shrink-0 rounded-full bg-primary" />
157→                )}
158→                <button
159→                  onClick={(e) => {
160→                    e.stopPropagation();
161→                    onDismiss(item.id);
162→                  }}
163→                  className="mt-0.5 shrink-0 rounded p-0.5 opacity-0 transition-opacity group-hover:opacity-100 hover:bg-muted"
164→                  title="Dismiss"
165→                >
166→                  <Trash2 className="size-3 text-muted-foreground" />
167→                </button>
168→              </div>
169→            );
170→          })
171→        )}
172→      </div>
173→    </div>
174→  );
175→}
