  1→"use client";
  2→
  3→import { useCallback, useEffect, useRef, useState } from "react";
  4→import { getAudioContext, decodeAudioData } from "@/lib/sound-engine";
  5→import type {
  6→  SoundAsset,
  7→  UseSoundOptions,
  8→  UseSoundReturn,
  9→} from "@/lib/sound-types";
 10→
 11→export function useSound(
 12→  sound: SoundAsset,
 13→  options: UseSoundOptions = {}
 14→): UseSoundReturn {
 15→  const {
 16→    volume = 1,
 17→    playbackRate = 1,
 18→    interrupt = false,
 19→    soundEnabled = true,
 20→    onPlay,
 21→    onEnd,
 22→    onPause,
 23→    onStop,
 24→  } = options;
 25→
 26→  const [isPlaying, setIsPlaying] = useState(false);
 27→  const [duration, setDuration] = useState<number | null>(
 28→    sound.duration ?? null
 29→  );
 30→  const sourceRef = useRef<AudioBufferSourceNode | null>(null);
 31→  const gainRef = useRef<GainNode | null>(null);
 32→  const bufferRef = useRef<AudioBuffer | null>(null);
 33→
 34→  useEffect(() => {
 35→    let cancelled = false;
 36→    decodeAudioData(sound.dataUri).then((buffer) => {
 37→      if (!cancelled) {
 38→        bufferRef.current = buffer;
 39→        setDuration(buffer.duration);
 40→      }
 41→    });
 42→    return () => {
 43→      cancelled = true;
 44→    };
 45→  }, [sound.dataUri]);
 46→
 47→  const stop = useCallback(() => {
 48→    if (sourceRef.current) {
 49→      try {
 50→        sourceRef.current.stop();
 51→      } catch {
 52→        // Already stopped
 53→      }
 54→      sourceRef.current = null;
 55→    }
 56→    setIsPlaying(false);
 57→    onStop?.();
 58→  }, [onStop]);
 59→
 60→  const play = useCallback(
 61→    (overrides?: { volume?: number; playbackRate?: number }) => {
 62→      if (!soundEnabled || !bufferRef.current) return;
 63→
 64→      const ctx = getAudioContext();
 65→
 66→      if (ctx.state === "suspended") {
 67→        ctx.resume();
 68→      }
 69→
 70→      if (interrupt && sourceRef.current) {
 71→        stop();
 72→      }
 73→
 74→      const source = ctx.createBufferSource();
 75→      const gain = ctx.createGain();
 76→
 77→      source.buffer = bufferRef.current;
 78→      source.playbackRate.value = overrides?.playbackRate ?? playbackRate;
 79→      gain.gain.value = overrides?.volume ?? volume;
 80→
 81→      source.connect(gain);
 82→      gain.connect(ctx.destination);
 83→
 84→      source.onended = () => {
 85→        setIsPlaying(false);
 86→        onEnd?.();
 87→      };
 88→
 89→      source.start(0);
 90→      sourceRef.current = source;
 91→      gainRef.current = gain;
 92→      setIsPlaying(true);
 93→      onPlay?.();
 94→    },
 95→    [soundEnabled, playbackRate, volume, interrupt, stop, onPlay, onEnd]
 96→  );
 97→
 98→  const pause = useCallback(() => {
 99→    stop();
100→    onPause?.();
101→  }, [stop, onPause]);
102→
103→  useEffect(() => {
104→    if (gainRef.current) {
105→      gainRef.current.gain.value = volume;
106→    }
107→  }, [volume]);
108→
109→  useEffect(() => {
110→    return () => {
111→      if (sourceRef.current) {
112→        try {
113→          sourceRef.current.stop();
114→        } catch {
115→          // Already stopped
116→        }
117→      }
118→    };
119→  }, []);
120→
121→  return [play, { stop, pause, isPlaying, duration, sound }] as const;
122→}
