  1→/**
  2→ * Sound effects module for thos.
  3→ *
  4→ * Maps agent events and tool types to sound pools. Each pool has
  5→ * multiple variants — a random one is picked on each play to keep
  6→ * it stimulating. Uses the Web Audio API via soundcn's sound engine.
  7→ *
  8→ * Settings (master volume, per-category volume/enabled) are persisted
  9→ * to localStorage and exposed via getSfxSettings/setSfxSettings.
 10→ */
 11→
 12→import { playSound } from "@/lib/sound-engine";
 13→import type { SoundAsset } from "@/lib/sound-types";
 14→
 15→// ── Impact sounds (Write / Edit / MultiEdit) ─────────────────────────
 16→import { impactGenericLight000Sound } from "@/lib/impact-generic-light-000";
 17→import { impactGenericLight001Sound } from "@/lib/impact-generic-light-001";
 18→import { impactGenericLight002Sound } from "@/lib/impact-generic-light-002";
 19→import { impactGenericLight003Sound } from "@/lib/impact-generic-light-003";
 20→import { impactGenericLight004Sound } from "@/lib/impact-generic-light-004";
 21→
 22→// ── Click sounds (Read) ──────────────────────────────────────────────
 23→import { clickSoftSound } from "@/lib/click-soft";
 24→import { click001Sound } from "@/lib/click-001";
 25→import { click002Sound } from "@/lib/click-002";
 26→import { click003Sound } from "@/lib/click-003";
 27→import { click004Sound } from "@/lib/click-004";
 28→
 29→// ── Glitch sounds (Bash) ─────────────────────────────────────────────
 30→import { glitch001Sound } from "@/lib/glitch-001";
 31→import { glitch002Sound } from "@/lib/glitch-002";
 32→import { glitch003Sound } from "@/lib/glitch-003";
 33→import { glitch004Sound } from "@/lib/glitch-004";
 34→
 35→// ── Tick sounds (Grep / Glob / search tools) ─────────────────────────
 36→import { tick001Sound } from "@/lib/tick-001";
 37→import { tick002Sound } from "@/lib/tick-002";
 38→import { tick004Sound } from "@/lib/tick-004";
 39→
 40→// ── Confirmation sounds (task result / done) ─────────────────────────
 41→import { confirmation001Sound } from "@/lib/confirmation-001";
 42→import { confirmation002Sound } from "@/lib/confirmation-002";
 43→import { confirmation003Sound } from "@/lib/confirmation-003";
 44→import { confirmation004Sound } from "@/lib/confirmation-004";
 45→
 46→// ── Error sounds ─────────────────────────────────────────────────────
 47→import { error001Sound } from "@/lib/error-001";
 48→import { error002Sound } from "@/lib/error-002";
 49→import { error003Sound } from "@/lib/error-003";
 50→
 51→// ── Question sounds (control requests / user prompts) ────────────────
 52→import { question001Sound } from "@/lib/question-001";
 53→import { question002Sound } from "@/lib/question-002";
 54→import { question003Sound } from "@/lib/question-003";
 55→
 56→// ── Select sounds (user message send) ─────────────────────────────────
 57→import { select001Sound } from "@/lib/select-001";
 58→import { select002Sound } from "@/lib/select-002";
 59→import { select003Sound } from "@/lib/select-003";
 60→
 61→// ── Session lifecycle ────────────────────────────────────────────────
 62→import { maximize001Sound } from "@/lib/maximize-001";
 63→import { maximize002Sound } from "@/lib/maximize-002";
 64→import { maximize003Sound } from "@/lib/maximize-003";
 65→import { maximize004Sound } from "@/lib/maximize-004";
 66→
 67→// ── Sound pools ──────────────────────────────────────────────────────
 68→
 69→const POOLS = {
 70→  codeWrite: [
 71→    impactGenericLight000Sound,
 72→    impactGenericLight001Sound,
 73→    impactGenericLight002Sound,
 74→    impactGenericLight003Sound,
 75→    impactGenericLight004Sound,
 76→  ],
 77→  codeRead: [
 78→    clickSoftSound,
 79→    click001Sound,
 80→    click002Sound,
 81→    click003Sound,
 82→    click004Sound,
 83→  ],
 84→  bash: [
 85→    glitch001Sound,
 86→    glitch002Sound,
 87→    glitch003Sound,
 88→    glitch004Sound,
 89→  ],
 90→  search: [
 91→    tick001Sound,
 92→    tick002Sound,
 93→    tick004Sound,
 94→  ],
 95→  done: [
 96→    confirmation001Sound,
 97→    confirmation002Sound,
 98→    confirmation003Sound,
 99→    confirmation004Sound,
100→  ],
101→  error: [
102→    error001Sound,
103→    error002Sound,
104→    error003Sound,
105→  ],
106→  question: [
107→    question001Sound,
108→    question002Sound,
109→    question003Sound,
110→  ],
111→  send: [
112→    select001Sound,
113→    select002Sound,
114→    select003Sound,
115→  ],
116→  begin: [
117→    maximize001Sound,
118→    maximize002Sound,
119→    maximize003Sound,
120→    maximize004Sound,
121→  ],
122→} as const;
123→
124→// ── Category registry (used by settings UI) ─────────────────────────
125→
126→export type SfxCategoryKey = keyof typeof POOLS;
127→
128→export interface SfxCategory {
129→  key: SfxCategoryKey;
130→  label: string;
131→  description: string;
132→  color: string;
133→  defaultVolume: number;
134→  pool: readonly SoundAsset[];
135→}
136→
137→export const SFX_CATEGORIES: SfxCategory[] = [
138→  { key: "codeWrite", label: "Code Write", description: "Write, Edit, MultiEdit", color: "bg-green-400", defaultVolume: 0.3, pool: POOLS.codeWrite },
139→  { key: "codeRead", label: "Code Read", description: "Read", color: "bg-blue-400", defaultVolume: 0.3, pool: POOLS.codeRead },
140→  { key: "bash", label: "Bash", description: "Bash", color: "bg-orange-400", defaultVolume: 0.3, pool: POOLS.bash },
141→  { key: "search", label: "Search", description: "Grep, Glob, WebFetch, WebSearch", color: "bg-purple-400", defaultVolume: 0.3, pool: POOLS.search },
142→  { key: "send", label: "Message Send", description: "User message send", color: "bg-lime-400", defaultVolume: 0.3, pool: POOLS.send },
143→  { key: "begin", label: "Session Start", description: "Agent session init", color: "bg-sky-400", defaultVolume: 0.35, pool: POOLS.begin },
