145→  { key: "error", label: "Error", description: "Errors", color: "bg-red-400", defaultVolume: 0.35, pool: POOLS.error },
146→  { key: "question", label: "Question", description: "Control requests, approvals", color: "bg-amber-400", defaultVolume: 0.4, pool: POOLS.question },
147→];
148→
149→// ── Tool → category mapping ─────────────────────────────────────────
150→
151→const TOOL_CATEGORY: Record<string, SfxCategoryKey> = {
152→  Write: "codeWrite",
153→  Edit: "codeWrite",
154→  MultiEdit: "codeWrite",
155→  NotebookEdit: "codeWrite",
156→  Read: "codeRead",
157→  Bash: "bash",
158→  Grep: "search",
159→  Glob: "search",
160→  Task: "search",
161→  WebFetch: "search",
162→  WebSearch: "search",
163→};
164→
165→// ── Settings ─────────────────────────────────────────────────────────
166→
167→export interface SfxCategorySettings {
168→  volume: number;   // 0–1
169→  enabled: boolean;
170→}
171→
172→export interface SfxSettings {
173→  master: number;   // 0–1
174→  muted: boolean;
175→  categories: Record<SfxCategoryKey, SfxCategorySettings>;
176→}
177→
178→const STORAGE_KEY = "thos-sfx-settings";
179→
180→function defaultSettings(): SfxSettings {
181→  const categories = {} as Record<SfxCategoryKey, SfxCategorySettings>;
182→  for (const cat of SFX_CATEGORIES) {
183→    categories[cat.key] = { volume: cat.defaultVolume, enabled: true };
184→  }
185→  return { master: 1, muted: false, categories };
186→}
187→
188→let _settings: SfxSettings | null = null;
189→
190→export function getSfxSettings(): SfxSettings {
191→  if (_settings) return _settings;
192→  if (typeof window === "undefined") return defaultSettings();
193→  try {
194→    const raw = localStorage.getItem(STORAGE_KEY);
195→    if (raw) {
196→      const parsed = JSON.parse(raw) as Partial<SfxSettings>;
197→      const defaults = defaultSettings();
198→      _settings = {
199→        master: parsed.master ?? defaults.master,
200→        muted: parsed.muted ?? defaults.muted,
201→        categories: { ...defaults.categories, ...parsed.categories },
202→      };
203→    } else {
204→      _settings = defaultSettings();
205→    }
206→  } catch {
207→    _settings = defaultSettings();
208→  }
209→  return _settings!;
210→}
211→
212→export function setSfxSettings(settings: SfxSettings) {
213→  _settings = settings;
214→  if (typeof window !== "undefined") {
215→    try {
216→      localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
217→    } catch {
218→      // Storage full or unavailable
219→    }
220→  }
221→}
222→
223→// ── Internal helpers ─────────────────────────────────────────────────
224→
225→function pick(pool: readonly SoundAsset[]): SoundAsset {
226→  return pool[Math.floor(Math.random() * pool.length)];
227→}
228→
229→function playCat(categoryKey: SfxCategoryKey) {
230→  const s = getSfxSettings();
231→  if (s.muted) return;
232→  const cat = s.categories[categoryKey];
233→  if (!cat?.enabled) return;
234→  const volume = cat.volume * s.master;
235→  if (volume <= 0) return;
236→  const pool = POOLS[categoryKey];
237→  playSound(pick(pool).dataUri, { volume });
238→}
239→
240→// ── Public API ───────────────────────────────────────────────────────
241→
242→/** Play SFX for a tool call. Returns silently if the tool has no mapped sound. */
243→export function sfxTool(toolName: string) {
244→  const cat = TOOL_CATEGORY[toolName];
245→  if (!cat) return;
246→  playCat(cat);
247→}
248→
249→/** Play SFX for a successful task result. */
250→export function sfxDone() {
251→  playCat("done");
252→}
253→
254→/** Play SFX for an error result. */
255→export function sfxError() {
256→  playCat("error");
257→}
258→
259→/** Play SFX for a control request / question prompt. */
260→export function sfxQuestion() {
261→  playCat("question");
262→}
263→
264→/** Play SFX when the user sends a message. */
265→export function sfxSend() {
266→  playCat("send");
267→}
268→
269→/** Play SFX for session start. */
270→export function sfxBegin() {
271→  playCat("begin");
272→}
273→
274→/** Preview a specific category's sound (ignores mute/enabled, uses category volume * master). */
275→export function sfxPreview(categoryKey: SfxCategoryKey) {
276→  const s = getSfxSettings();
277→  const cat = s.categories[categoryKey];
278→  const volume = (cat?.volume ?? 0.3) * s.master;
279→  const pool = POOLS[categoryKey];
280→  playSound(pick(pool).dataUri, { volume: Math.max(volume, 0.1) });
281→}
