 1→let audioContext: AudioContext | null = null;
 2→const bufferCache = new Map<string, AudioBuffer>();
 3→
 4→export function getAudioContext(): AudioContext {
 5→  if (!audioContext) {
 6→    audioContext = new AudioContext();
 7→  }
 8→  return audioContext;
 9→}
10→
11→export async function decodeAudioData(dataUri: string): Promise<AudioBuffer> {
12→  const cached = bufferCache.get(dataUri);
13→  if (cached) return cached;
14→
15→  const ctx = getAudioContext();
16→  const base64 = dataUri.split(",")[1];
17→  const binaryString = atob(base64);
18→  const bytes = new Uint8Array(binaryString.length);
19→  for (let i = 0; i < binaryString.length; i++) {
20→    bytes[i] = binaryString.charCodeAt(i);
21→  }
22→
23→  const audioBuffer = await ctx.decodeAudioData(bytes.buffer.slice(0));
24→  bufferCache.set(dataUri, audioBuffer);
25→  return audioBuffer;
26→}
27→
28→export interface PlaySoundOptions {
29→  volume?: number;
30→  playbackRate?: number;
31→  onEnd?: () => void;
32→}
33→
34→export interface SoundPlayback {
35→  stop: () => void;
36→}
37→
38→export async function playSound(
39→  dataUri: string,
40→  options: PlaySoundOptions = {}
41→): Promise<SoundPlayback> {
42→  const { volume = 1, playbackRate = 1, onEnd } = options;
43→  const ctx = getAudioContext();
44→  if (ctx.state === "suspended") {
45→    await ctx.resume();
46→  }
47→
48→  const buffer = await decodeAudioData(dataUri);
49→  const source = ctx.createBufferSource();
50→  const gain = ctx.createGain();
51→
52→  source.buffer = buffer;
53→  source.playbackRate.value = playbackRate;
54→  gain.gain.value = volume;
55→
56→  source.connect(gain);
57→  gain.connect(ctx.destination);
58→
59→  source.onended = () => {
60→    onEnd?.();
61→  };
62→
63→  source.start(0);
64→
65→  return {
66→    stop: () => {
67→      try {
68→        source.stop();
69→      } catch {
70→        // No-op if already stopped.
71→      }
72→    },
73→  };
74→}
75→

 1→export interface SoundAsset {
 2→  /** Unique identifier for the sound */
 3→  name: string;
 4→  /** Base64-encoded data URI (data:audio/mpeg;base64,...) */
 5→  dataUri: string;
 6→  /** Duration in seconds */
 7→  duration: number;
 8→  /** Audio format */
 9→  format: "mp3" | "wav" | "ogg";
10→  /** License identifier */
11→  license: "CC0" | "OGA-BY" | "MIT";
12→  /** Original author/creator */
13→  author: string;
14→}
15→
16→export interface UseSoundOptions {
17→  /** Volume level from 0 to 1. Default: 1 */
18→  volume?: number;
19→  /** Playback speed multiplier. Default: 1 */
20→  playbackRate?: number;
21→  /** If true, calling play() stops current playback first. Default: false */
22→  interrupt?: boolean;
23→  /** If false, play() does nothing. Useful for user preferences. Default: true */
24→  soundEnabled?: boolean;
25→  /** Called when playback starts */
26→  onPlay?: () => void;
27→  /** Called when playback ends naturally */
28→  onEnd?: () => void;
29→  /** Called when pause() is called */
30→  onPause?: () => void;
31→  /** Called when stop() is called */
32→  onStop?: () => void;
33→}
34→
35→export type PlayFunction = (overrides?: {
36→  volume?: number;
37→  playbackRate?: number;
38→}) => void;
39→
40→export interface SoundControls {
41→  stop: () => void;
42→  pause: () => void;
43→  isPlaying: boolean;
44→  duration: number | null;
45→  sound: SoundAsset;
46→}
47→
48→export type UseSoundReturn = readonly [PlayFunction, SoundControls];
