  1→/**
  2→ * Notification module for thos dashboard.
  3→ *
  4→ * Handles two ephemeral notification channels:
  5→ * 1. **Browser/OS notifications** (Web Notifications API) — shown when the tab
  6→ *    is hidden so the user knows an agent needs attention.
  7→ * 2. **In-app toasts** (Sonner) — shown for events from non-active agents.
  8→ *
  9→ * The persistent notification inbox is managed separately in the useWebSocket
 10→ * hook as React state. This module only handles fire-and-forget alerts.
 11→ *
 12→ * Both channels respect a global enabled/disabled toggle persisted in
 13→ * localStorage. The module pattern mirrors `lib/sfx.ts`.
 14→ */
 15→
 16→import { toast } from "sonner";
 17→
 18→const STORAGE_KEY = "thos-notifications-enabled";
 19→
 20→let enabled = false;
 21→
 22→/** Read persisted state from localStorage. Call once on mount. */
 23→export function initNotifications() {
 24→  if (typeof window === "undefined") return;
 25→  const stored = localStorage.getItem(STORAGE_KEY);
 26→  enabled = stored === null ? true : stored === "true";
 27→}
 28→
 29→export function isNotificationsEnabled(): boolean {
 30→  return enabled;
 31→}
 32→
 33→export function setNotificationsEnabled(value: boolean) {
 34→  enabled = value;
 35→  if (typeof window !== "undefined") {
 36→    localStorage.setItem(STORAGE_KEY, String(value));
 37→  }
 38→}
 39→
 40→/** Request browser notification permission. Returns true if granted. */
 41→export async function requestPermission(): Promise<boolean> {
 42→  if (typeof window === "undefined" || !("Notification" in window)) {
 43→    console.warn("[thos-notif] Notification API not available — requires HTTPS or localhost");
 44→    return false;
 45→  }
 46→  if (Notification.permission === "granted") return true;
 47→  if (Notification.permission === "denied") {
 48→    console.warn("[thos-notif] Permission denied — user must reset in browser settings");
 49→    return false;
 50→  }
 51→  try {
 52→    const result = await Notification.requestPermission();
 53→    console.log("[thos-notif] Permission result:", result);
 54→    return result === "granted";
 55→  } catch (e) {
 56→    console.error("[thos-notif] requestPermission failed:", e);
 57→    return false;
 58→  }
 59→}
 60→
 61→// ── Notification options ──────────────────────────────────────────────────
 62→
 63→interface NotifyOptions {
 64→  agentId: string;
 65→  agentLabel: string;
 66→  /** True if this is the currently viewed agent — skips in-app toast. */
 67→  isActiveAgent: boolean;
 68→}
 69→
 70→interface ControlRequestOptions extends NotifyOptions {
 71→  toolName: string;
 72→}
 73→
 74→// ── Internal helpers ──────────────────────────────────────────────────────
 75→
 76→function browserNotify(title: string, body: string) {
 77→  if (!("Notification" in window)) return;
 78→  if (Notification.permission !== "granted") return;
 79→  if (!document.hidden) return;
 80→
 81→  const n = new Notification(title, {
 82→    body,
 83→    silent: true, // SFX system handles sounds
 84→  });
 85→  n.onclick = () => {
 86→    window.focus();
 87→    n.close();
 88→  };
 89→}
 90→
 91→function inAppToast(
 92→  type: "success" | "error" | "warning" | "info",
 93→  message: string,
 94→  opts: NotifyOptions
 95→) {
 96→  if (opts.isActiveAgent) return;
 97→
 98→  const label = opts.agentLabel || opts.agentId.slice(0, 8);
 99→  const toastFn = type === "warning" ? toast.warning : toast[type];
100→
101→  toastFn(message, {
102→    description: label,
103→    duration: type === "warning" || type === "error" ? 8000 : 5000,
104→  });
105→}
106→
107→// ── Public notification functions ─────────────────────────────────────────
108→
109→export function notifyDone(opts: NotifyOptions) {
110→  if (!enabled) return;
111→  const label = opts.agentLabel || opts.agentId.slice(0, 8);
112→  browserNotify("Agent finished", label);
113→  inAppToast("success", "Agent finished", opts);
114→}
115→
116→export function notifyError(opts: NotifyOptions) {
117→  if (!enabled) return;
118→  const label = opts.agentLabel || opts.agentId.slice(0, 8);
119→  browserNotify("Agent error", label);
120→  inAppToast("error", "Agent error", opts);
121→}
122→
123→export function notifyControlRequest(opts: ControlRequestOptions) {
124→  if (!enabled) return;
125→  const label = opts.agentLabel || opts.agentId.slice(0, 8);
126→  browserNotify("Approval needed", `${label} — ${opts.toolName}`);
127→  inAppToast("warning", `Approval needed: ${opts.toolName}`, opts);
128→}
129→
130→export function notifyQuestion(opts: NotifyOptions) {
131→  if (!enabled) return;
132→  const label = opts.agentLabel || opts.agentId.slice(0, 8);
133→  browserNotify("Question from agent", label);
134→  inAppToast("info", "Question from agent", opts);
135→}
136→
137→/** Send a test notification (bypasses document.hidden check). Returns a diagnostic string. */
138→export function sendTestNotification(): string {
139→  const secure = window.isSecureContext ? "yes" : "no";
140→  const hasApi = "Notification" in window ? "yes" : "no";
141→  const perm = "Notification" in window ? Notification.permission : "n/a";
142→  const diag = `secure=${secure} api=${hasApi} perm=${perm} enabled=${enabled}`;
143→
144→  if (!("Notification" in window)) return `No Notification API (${diag})`;
145→  if (Notification.permission !== "granted") return `Permission: ${Notification.permission} (${diag})`;
146→
147→  try {
148→    const n = new Notification("thos — test", {
149→      body: "Desktop notifications are working",
150→      silent: true,
151→    });
152→    n.onclick = () => {
153→      window.focus();
154→      n.close();
155→    };
156→    return "sent";
157→  } catch (e) {
158→    return `${e instanceof Error ? e.message : String(e)} (${diag})`;
159→  }
160→}
