371→                }}
372→              />
373→            )}
374→            <ContextMenuItem
375→              label="Clear History"
376→              onClick={() => {
377→                onClearHistory(ctxMenu.agentId);
378→                closeMenu();
379→              }}
380→            />
381→            <div className="my-1 border-t" />
382→            <ContextMenuItem
383→              label="Delete"
384→              destructive
385→              onClick={() => {
386→                closeMenu();
387→                if (confirm("Delete this agent? This cannot be undone.")) {
388→                  onDelete(ctxMenu.agentId);
389→                }
390→              }}
391→            />
392→          </div>,
393→          document.body
394→        );
395→      })()}
396→    </div>
397→  );
