 279→interface UseWebSocketOptions {
 280→  /** Agent ID from URL. Controls which agent is active. */
 281→  activeAgentId: string | null;
 282→  /** Called when the hook wants to change the active agent (spawn, delete, auto-select). */
 283→  onNavigateToAgent: (agentId: string | null) => void;
 284→}
 285→
 286→export function useWebSocket(options: UseWebSocketOptions) {
 287→  const { activeAgentId, onNavigateToAgent } = options;
 288→
 289→  const wsRef = useRef<WebSocket | null>(null);
 290→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
 291→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
 292→  const closingRef = useRef(false);
 293→  const [connected, setConnected] = useState(false);
 294→  /** True once we've received the initial agent_list from the server. */
 295→  const [initialLoadDone, setInitialLoadDone] = useState(false);
 296→
 297→  // Multi-agent state
 298→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
 299→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
 300→
 301→  // Task state
 302→  const [tasks, setTasks] = useState<Task[]>([]);
 303→
 304→  // Workspace state
 305→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
 306→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
 307→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
 308→
 309→  // Notification inbox state
 310→  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
 311→  let notifCounter = useRef(0);
 312→
 313→  // Refs for accessing current state inside the onmessage closure.
 314→  const activeAgentIdRef = useRef(activeAgentId);
 315→  activeAgentIdRef.current = activeAgentId;
 316→  const onNavigateRef = useRef(onNavigateToAgent);
 317→  onNavigateRef.current = onNavigateToAgent;
 318→  const agentsRef = useRef(agents);
 319→  agentsRef.current = agents;
 320→
 321→  // Per-agent deduplication: track count of processed messages per agent
 322→  // to avoid duplicating messages already in local state during history replay.
 323→  const processedCountRef = useRef<Map<string, number>>(new Map());
 324→
 325→  // Track which agents have had their history loaded (lazy loading).
 326→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
 327→
 328→  /** Immutably update a single agent's state in the Map. */
 329→  const updateAgent = useCallback(
 330→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
 331→      setAgents((prev) => {
 332→        const existing = prev.get(agentId);
 333→        if (!existing) return prev;
 334→        const next = new Map(prev);
 335→        next.set(agentId, updater(existing));
 336→        return next;
 337→      });
 338→    },
 339→    []
 340→  );
 341→
 342→  /** Build notification options for an agent event. */
 343→  const notifyOpts = (agentId: string) => {
 344→    const agent = agentsRef.current.get(agentId);
 345→    return {
 346→      agentId,
 347→      agentLabel: agent?.label || agentId.slice(0, 8),
 348→      isActiveAgent: agentId === activeAgentIdRef.current,
 349→    };
 350→  };
 351→
 352→  /** Push a notification item to the inbox. */
 353→  const pushNotification = (type: NotificationType, agentId: string, message: string) => {
 354→    const agent = agentsRef.current.get(agentId);
 355→    const item: NotificationItem = {
 356→      id: `notif-${Date.now()}-${++notifCounter.current}`,
 357→      type,
 358→      agentId,
 359→      agentLabel: agent?.label || agentId.slice(0, 8),
 360→      message,
 361→      timestamp: Date.now(),
 362→      read: false,
 363→    };
 364→    setNotifications((prev) => [item, ...prev]);
 365→  };
 366→
 367→  const connect = useCallback(() => {
 368→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
 369→    if (wsRef.current) {
 370→      wsRef.current.close();
 371→      wsRef.current = null;
 372→    }
 373→
 374→    // Reset dedup counts on new connection — server will send fresh history
 375→    processedCountRef.current.clear();
 376→    setInitialLoadDone(false);
 377→    setLoadedAgents(new Set());
 378→
 379→    log("connecting to", WS_URL);
 380→    const ws = new WebSocket(WS_URL);
 381→    wsRef.current = ws;
 382→
 383→    ws.onopen = () => {
 384→      log("connected");
 385→      setConnected(true);
 386→    };
 387→
 388→    ws.onclose = () => {
 389→      log("disconnected, closingRef =", closingRef.current);
 390→      setConnected(false);
 391→      wsRef.current = null;
 392→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
 393→      if (closingRef.current) return;
 394→      // Reconnection guard: clear any existing timer before scheduling
 395→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
 396→      log("scheduling reconnect in 2s");
 397→      reconnectTimer.current = setTimeout(() => connect(), 2000);
 398→    };
 399→
 400→    ws.onerror = (e) => {
 401→      log("error", e);
 402→      // onclose will fire after onerror, which triggers reconnect
 403→    };
 404→
 405→    ws.onmessage = (event) => {
 406→      let data: ServerMessage;
 407→      try {
 408→        data = JSON.parse(event.data as string);
 409→      } catch {
 410→        return;
 411→      }
 412→
 413→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
 414→
 415→      // ── workspace_list: full workspace list from server ──
 416→      if (data.type === "workspace_list") {
 417→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
 418→        log("workspace_list:", wsList.length, "workspaces");
 419→        setWorkspaces(wsList);
 420→        return;
 421→      }
 422→
 423→      // ── directory_listing: response to browse_directory ──
 424→      if (data.type === "directory_listing") {
 425→        const listing = data as { path: string; entries: DirectoryEntry[] };
 426→        log("directory_listing:", listing.path, listing.entries.length, "entries");
 427→        setDirectoryListing({ path: listing.path, entries: listing.entries });
 428→        return;
 429→      }
 430→
 431→      // ── task_list: full task list from server ──
 432→      if (data.type === "task_list") {
 433→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
 434→        setTasks((data as ServerTaskList).tasks);
 435→        return;
 436→      }
 437→
 438→      // ── task_updated: single task changed ──
 439→      if (data.type === "task_updated") {
 440→        const updated = (data as ServerTaskUpdated).task;
 441→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
 442→        return;
 443→      }
 444→
 445→      // ── task_deleted: remove task ──
 446→      if (data.type === "task_deleted") {
 447→        const deletedId = (data as ServerTaskDeleted).taskId;
 448→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
 449→        return;
 450→      }
 451→
 452→      // ── message_history: replay full history from server ──
 453→      if (data.type === "message_history") {
 454→        const historyMsg = data as ServerMessageHistory;
 455→        const agentId = historyMsg.agentId;
 456→        const serverMessages = historyMsg.messages;
 457→        log("message_history:", agentId, serverMessages.length, "raw msgs");
 458→
 459→        // Convert all server messages to ChatMessages + extract raw Claude messages
 460→        const chatMessages: ChatMessage[] = [];
 461→        const rawMessages: ClaudeMessage[] = [];
 462→        for (const sm of serverMessages) {
 463→          if (sm.type === "relay") {
 464→            rawMessages.push(sm.message);
 465→          }
 466→          const cm = relayChatMessage(agentId, sm);
 467→          if (cm) chatMessages.push(cm);
 468→        }
 469→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
 470→
 471→        // Always replace local messages with server history (source of truth).
 472→        setAgents((prev) => {
 473→          const existing = prev.get(agentId);
 474→          if (!existing) {
 475→            log("message_history:", agentId, "agent not in map yet, creating");
 476→            const next = new Map(prev);
 477→            next.set(agentId, {
 478→              status: "idle",
 479→              messages: chatMessages,
 480→              rawMessages,
 481→              label: "",
 482→              tmuxSession: null,
 483→              createdAt: 0,
 484→            });
 485→            return next;
 486→          }
 487→          const next = new Map(prev);
 488→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
 489→          return next;
 490→        });
 491→
 492→        processedCountRef.current.set(agentId, chatMessages.length);
 493→        setLoadedAgents((prev) => {
 494→          if (prev.has(agentId)) return prev;
 495→          const next = new Set(prev);
 496→          next.add(agentId);
 497→          return next;
 498→        });
 499→        return;
 500→      }
 501→
 502→      // ── history_cleared: wipe local messages for this agent ──
 503→      if (data.type === "history_cleared") {
 504→        updateAgent(data.agentId, (prev) => ({
 505→          ...prev,
 506→          messages: [],
 507→          rawMessages: [],
 508→        }));
 509→        processedCountRef.current.set(data.agentId, 0);
 510→        return;
 511→      }
 512→
 513→      // ── cli_disconnected: show system message ──
 514→      if (data.type === "cli_disconnected") {
 515→        updateAgent(data.agentId, (prev) => ({
 516→          ...prev,
 517→          messages: [
 518→            ...prev.messages,
 519→            {
 520→              id: nextId(),
 521→              role: "system",
 522→              content: "CLI session ended",
 523→              timestamp: Date.now(),
 524→            },
 525→          ],
 526→        }));
 527→        return;
 528→      }
 529→
 530→      // ── cli_connected: show system message ──
 531→      if (data.type === "cli_connected") {
 532→        updateAgent(data.agentId, (prev) => ({
 533→          ...prev,
 534→          messages: [
 535→            ...prev.messages,
 536→            {
 537→              id: nextId(),
 538→              role: "system",
 539→              content: "CLI reconnected",
 540→              timestamp: Date.now(),
 541→            },
 542→          ],
 543→        }));
 544→        return;
 545→      }
 546→
 547→      // ── agent_list: reconcile sidebar state from server ──
 548→      if (data.type === "agent_list") {
 549→        const serverAgents = data.agents as AgentInfo[];
 550→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
 551→        setAgents((prev) => {
 552→          const next = new Map(prev);
 553→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
 554→
 555→          // Update or add agents from server
 556→          for (const info of serverAgents) {
 557→            const existing = next.get(info.agentId);
 558→            if (existing) {
 559→              next.set(info.agentId, {
 560→                ...existing,
 561→                status: info.status,
 562→                tmuxSession: info.tmuxSession,
 563→                label: info.label,
 564→                model: info.model ?? existing.model,
 565→                pinned: info.pinned ?? false,
 566→                iceboxed: info.iceboxed ?? false,
 567→                workspaceId: info.workspaceId,
 568→              });
 569→            } else {
 570→              next.set(info.agentId, {
 571→                status: info.status,
 572→                messages: [],
 573→                rawMessages: [],
 574→                label: info.label,
 575→                tmuxSession: info.tmuxSession,
 576→                createdAt: info.createdAt,
 577→                model: info.model ?? undefined,
 578→                pinned: info.pinned ?? false,
 579→                iceboxed: info.iceboxed ?? false,
 580→                workspaceId: info.workspaceId,
 581→              });
 582→            }
 583→          }
 584→
 585→          // Remove agents no longer on the server
 586→          for (const id of next.keys()) {
 587→            if (!serverIds.has(id)) {
 588→              next.delete(id);
 589→            }
 590→          }
 591→
 592→          return next;
 593→        });
 594→        setAgentOrder(serverAgents.map((a) => a.agentId));
 595→        setInitialLoadDone(true);
 596→
 597→        // Auto-select first agent when none selected, or redirect stale IDs
 598→        const currentId = activeAgentIdRef.current;
 599→        const serverIds = new Set(serverAgents.map((a) => a.agentId));
 600→        if (currentId === null && serverAgents.length > 0) {
 601→          onNavigateRef.current(serverAgents[0].agentId);
 602→        } else if (currentId !== null && !serverIds.has(currentId) && serverAgents.length > 0) {
 603→          onNavigateRef.current(serverAgents[0].agentId);
 604→        }
 605→        return;
 606→      }
 607→
 608→      // ── spawned: auto-select the newly created agent ──
 609→      if (data.type === "spawned") {
 610→        onNavigateRef.current(data.agentId);
 611→        return;
 612→      }
 613→
 614→      // ── status: update a specific agent's status ──
 615→      if (data.type === "status") {
 616→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
 617→        return;
 618→      }
 619→
 620→      // ── error: append to agent's message list ──
 621→      if (data.type === "error") {
 622→        sfxError();
 623→        updateAgent(data.agentId, (prev) => ({
 624→          ...prev,
 625→          messages: [
 626→            ...prev.messages,
 627→            {
 628→              id: nextId(),
 629→              role: "system",
 630→              content: `Error: ${data.error}`,
 631→              timestamp: Date.now(),
 632→            },
 633→          ],
 634→        }));
 635→        // Track processed count for dedup
 636→        processedCountRef.current.set(
 637→          data.agentId,
 638→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
 639→        );
 640→        return;
 641→      }
 642→
 643→      // ── relay: append claude message to agent's history ──
 644→      if (data.type === "relay") {
 645→        const agentId = data.agentId;
 646→        const rawMsg = data.message;
 647→        const chatMsg = relayChatMessage(agentId, data);
 648→
 649→        // SFX: play a sound for each tool call in the message
 650→        if (chatMsg?.toolCalls?.length) {
 651→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
 652→          const first = chatMsg.toolCalls.find((tc) => tc.name);
 653→          if (first) sfxTool(first.name);
 654→        }
 655→
 656→        // SFX + notifications: result done / error
 657→        if (rawMsg.type === "result") {
 658→          const result = rawMsg as ClaudeResult;
 659→          if (result.is_error) {
 660→            sfxError();
 661→            notifyError(notifyOpts(agentId));
 662→            pushNotification("error", agentId, "Agent error");
 663→          } else {
 664→            sfxDone();
 665→            notifyDone(notifyOpts(agentId));
 666→            pushNotification("done", agentId, "Agent finished");
 667→          }
 668→        }
 669→
 670→        // SFX + notifications: control request (tool approval / question)
 671→        if (rawMsg.type === "control_request") {
 672→          sfxQuestion();
 673→          const cr = rawMsg as ClaudeControlRequest;
 674→          if (cr.request.tool_name === "AskUserQuestion") {
 675→            notifyQuestion(notifyOpts(agentId));
 676→            pushNotification("question", agentId, "Question from agent");
 677→          } else {
 678→            notifyControlRequest({
 679→              ...notifyOpts(agentId),
 680→              toolName: cr.request.tool_name,
 681→            });
 682→            pushNotification("control_request", agentId, `Approval needed: ${cr.request.tool_name}`);
 683→          }
 684→        }
 685→
 686→        // SFX: session start
 687→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
 688→          sfxBegin();
 689→        }
 690→
 691→        // Capture model from system/init
 692→        const initModel =
 693→          rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init"
 694→            ? (rawMsg as ClaudeSystemInit).model
 695→            : undefined;
 696→
 697→        updateAgent(agentId, (prev) => ({
 698→          ...prev,
 699→          rawMessages: [...prev.rawMessages, rawMsg],
 700→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
 701→          ...(initModel ? { model: initModel } : {}),
 702→        }));
 703→        if (chatMsg) {
 704→          // Track processed count for dedup
 705→          processedCountRef.current.set(
 706→            agentId,
 707→            (processedCountRef.current.get(agentId) ?? 0) + 1
 708→          );
 709→        }
 710→        return;
 711→      }
 712→    };
 713→  }, [updateAgent]);
 714→
 715→  useEffect(() => {
 716→    closingRef.current = false;
 717→    connect();
 718→    return () => {
 719→      closingRef.current = true;
 720→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
 721→      wsRef.current?.close();
 722→    };
 723→  }, [connect]);
 724→
 725→  const send = useCallback((data: object) => {
 726→    if (wsRef.current?.readyState === WebSocket.OPEN) {
 727→      wsRef.current.send(JSON.stringify(data));
 728→    }
 729→  }, []);
 730→
 731→  // Request history for the active agent if not already loaded.
 732→  useEffect(() => {
 733→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
 734→    log("requesting history for", activeAgentId);
 735→    send({ type: "request_history", agentId: activeAgentId });
 736→  }, [activeAgentId, loadedAgents, send]);
 737→
 738→  const spawnAgent = useCallback(
 739→    (prompt: string, model?: string, systemPrompt?: string) => {
