 935→  // Derived values for the active agent
 936→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
 937→  const activeStatus = useMemo<AgentStatus>(
 938→    () => activeAgent?.status ?? "idle",
 939→    [activeAgent?.status]
 940→  );
 941→  const activeMessages = useMemo<ChatMessage[]>(
 942→    () => activeAgent?.messages ?? [],
 943→    [activeAgent?.messages]
 944→  );
 945→  const activeRawMessages = useMemo<ClaudeMessage[]>(
 946→    () => activeAgent?.rawMessages ?? [],
 947→    [activeAgent?.rawMessages]
 948→  );
 949→  const activeModel = activeAgent?.model ?? null;
 950→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
 951→
 952→  // ── Notification inbox actions ──────────────────────────────────────────
 953→
 954→  const clearNotifications = useCallback(() => {
 955→    setNotifications([]);
 956→  }, []);
 957→
 958→  const dismissNotification = useCallback((id: string) => {
 959→    setNotifications((prev) => prev.filter((n) => n.id !== id));
 960→  }, []);
