 962→  const markNotificationRead = useCallback((id: string) => {
 963→    setNotifications((prev) =>
 964→      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
 965→    );
 966→  }, []);
 967→
 968→  const testNotification = useCallback(() => {
 969→    pushNotification("done", "test", "Test notification");
 970→  }, []);
 971→
 972→  return {
