  1→/**
  2→ * File-based session persistence for thos agents.
  3→ *
  4→ * Persists agent state + message history to JSON files in
  5→ * `.thos/sessions/<agentId>.json` so data survives server restarts.
  6→ *
  7→ * Uses debounced writes (150ms) for high-frequency events (streaming) and
  8→ * synchronous writes for critical state changes (spawn, result, status).
  9→ */
 10→
 11→import { mkdirSync, writeFileSync, readFileSync, readdirSync, unlinkSync, existsSync } from "fs";
 12→import { join } from "path";
 13→import type { AgentStatus, ServerMessage } from "../lib/types";
 14→
 15→const SESSION_DIR = join(process.cwd(), ".thos", "sessions");
 16→
 17→/** Shape of a persisted agent on disk. */
 18→export interface PersistedAgent {
 19→  id: string;
 20→  state: {
 21→    agentId: string;
 22→    status: AgentStatus;
 23→    tmuxSession: string | null;
 24→    label: string;
 25→    createdAt: number;
 26→    sessionId: string | null;
 27→    workspaceId: string | null;
 28→    model?: string | null;
 29→    pinned?: boolean;
 30→    iceboxed?: boolean;
 31→  };
 32→  messageHistory: ServerMessage[];
 33→}
 34→
 35→export class SessionStore {
 36→  private dir: string;
 37→  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>();
 38→
 39→  constructor(dir: string = SESSION_DIR) {
 40→    this.dir = dir;
 41→    mkdirSync(this.dir, { recursive: true });
 42→  }
 43→
 44→  /** File path for a given agent ID. */
 45→  private filePath(agentId: string): string {
 46→    return join(this.dir, `${agentId}.json`);
 47→  }
 48→
 49→  /** Debounced write — batches rapid stream events (150ms). */
 50→  save(agent: PersistedAgent): void {
 51→    const existing = this.debounceTimers.get(agent.id);
 52→    if (existing) clearTimeout(existing);
 53→    this.debounceTimers.set(
 54→      agent.id,
 55→      setTimeout(() => {
 56→        this.debounceTimers.delete(agent.id);
 57→        this.writeFile(agent);
 58→      }, 150)
 59→    );
 60→  }
 61→
 62→  /** Immediate write — use for critical state changes (spawn, result, status). */
 63→  saveSync(agent: PersistedAgent): void {
 64→    // Cancel any pending debounced write
 65→    const existing = this.debounceTimers.get(agent.id);
 66→    if (existing) {
 67→      clearTimeout(existing);
 68→      this.debounceTimers.delete(agent.id);
 69→    }
 70→    this.writeFile(agent);
 71→  }
 72→
 73→  /** Load a single agent from disk. Returns null if not found. */
 74→  load(agentId: string): PersistedAgent | null {
 75→    const fp = this.filePath(agentId);
 76→    if (!existsSync(fp)) return null;
 77→    try {
 78→      const raw = readFileSync(fp, "utf-8");
 79→      return JSON.parse(raw) as PersistedAgent;
 80→    } catch (err) {
 81→      console.error(`[session-store] failed to load ${agentId}:`, err);
 82→      return null;
 83→    }
 84→  }
 85→
 86→  /** Load all persisted agents on server startup. */
 87→  loadAll(): PersistedAgent[] {
 88→    try {
 89→      const files = readdirSync(this.dir).filter((f) => f.endsWith(".json"));
 90→      const agents: PersistedAgent[] = [];
 91→      for (const file of files) {
 92→        try {
 93→          const raw = readFileSync(join(this.dir, file), "utf-8");
 94→          agents.push(JSON.parse(raw) as PersistedAgent);
 95→        } catch (err) {
 96→          console.error(`[session-store] failed to parse ${file}:`, err);
 97→        }
 98→      }
 99→      return agents;
100→    } catch {
101→      return [];
102→    }
103→  }
104→
105→  /** Delete an agent's persisted file. */
106→  remove(agentId: string): void {
107→    const fp = this.filePath(agentId);
108→    try {
109→      if (existsSync(fp)) unlinkSync(fp);
110→    } catch (err) {
111→      console.error(`[session-store] failed to remove ${agentId}:`, err);
112→    }
113→    // Also cancel any pending debounced write
114→    const existing = this.debounceTimers.get(agentId);
115→    if (existing) {
116→      clearTimeout(existing);
117→      this.debounceTimers.delete(agentId);
118→    }
119→  }
120→
121→  /** Flush all pending debounced writes synchronously (for graceful shutdown). */
122→  flushAll(allAgents: PersistedAgent[]): void {
123→    // Cancel all pending timers
124→    for (const [id, timer] of this.debounceTimers) {
125→      clearTimeout(timer);
126→      this.debounceTimers.delete(id);
127→    }
128→    // Write all agents
129→    for (const agent of allAgents) {
130→      this.writeFile(agent);
131→    }
132→  }
133→
134→  private writeFile(agent: PersistedAgent): void {
135→    try {
136→      writeFileSync(this.filePath(agent.id), JSON.stringify(agent, null, 2));
137→    } catch (err) {
138→      console.error(`[session-store] failed to write ${agent.id}:`, err);
139→    }
140→  }
141→}
