  3→/**
  4→ * Workspace dropdown in the sidebar header.
  5→ *
  6→ * Shows the active workspace name (or "All Workspaces"), with a dropdown
  7→ * listing all workspaces plus an "Open Folder..." option that triggers
  8→ * the folder browser modal.
  9→ */
 10→
 11→import { useCallback, useEffect, useRef, useState } from "react";
 12→import { ChevronDown, FolderOpen, Pencil, Trash2 } from "lucide-react";
 13→import type { Workspace } from "@/lib/types";
 14→import { Tip } from "@/components/ui/tip";
 15→import { cn } from "@/lib/utils";
 16→
 17→export function WorkspaceSwitcher({
 18→  workspaces,
 19→  activeWorkspaceId,
 20→  onSelect,
 21→  onRename,
 22→  onDelete,
 23→  onOpenFolder,
 24→}: {
 25→  workspaces: Workspace[];
 26→  activeWorkspaceId: string | null;
 27→  onSelect: (workspaceId: string | null) => void;
 28→  onRename: (workspaceId: string, name: string) => void;
 29→  onDelete: (workspaceId: string) => void;
 30→  onOpenFolder: () => void;
 31→}) {
 32→  const [open, setOpen] = useState(false);
 33→  const [renamingId, setRenamingId] = useState<string | null>(null);
 34→  const dropdownRef = useRef<HTMLDivElement>(null);
 35→
 36→  const activeWorkspace = activeWorkspaceId
 37→    ? workspaces.find((w) => w.id === activeWorkspaceId)
 38→    : null;
 39→
 40→  // Close on click-outside or Escape
 41→  useEffect(() => {
 42→    if (!open) return;
 43→    function handleClick(e: MouseEvent) {
 44→      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
 45→        setOpen(false);
 46→      }
 47→    }
 48→    function handleKey(e: KeyboardEvent) {
 49→      if (e.key === "Escape") setOpen(false);
 50→    }
 51→    document.addEventListener("mousedown", handleClick);
 52→    document.addEventListener("keydown", handleKey);
 53→    return () => {
 54→      document.removeEventListener("mousedown", handleClick);
 55→      document.removeEventListener("keydown", handleKey);
 56→    };
 57→  }, [open]);
 58→
 59→  const handleSelect = useCallback(
 60→    (id: string | null) => {
 61→      onSelect(id);
 62→      setOpen(false);
 63→    },
 64→    [onSelect]
 65→  );
 66→
 67→  return (
 68→    <div className="relative" ref={dropdownRef}>
 69→      <button
 70→        onClick={() => setOpen((v) => !v)}
 71→        className="flex w-full items-center gap-1.5 rounded px-3 py-2 text-left text-sm transition-colors hover:bg-sidebar-accent"
 72→      >
 73→        <span className="flex min-w-0 flex-1 flex-col">
 74→          <Tip text={activeWorkspace?.name ?? "All Workspaces"} side="right">
 75→            <span className="text-primary font-bold text-sm tracking-tight truncate">
 76→              {activeWorkspace?.name ?? "All Workspaces"}
 77→            </span>
 78→          </Tip>
 79→          {activeWorkspace && (
 80→            <Tip text={activeWorkspace.cwd} side="right">
 81→              <span className="text-[10px] text-muted-foreground truncate">
 82→                {activeWorkspace.cwd}
 83→              </span>
 84→            </Tip>
 85→          )}
 86→        </span>
 87→        <ChevronDown className={cn("size-3.5 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} />
 88→      </button>
 89→
 90→      {open && (
 91→        <div className="absolute left-0 top-full z-50 mt-1 w-full min-w-[200px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md">
 92→          {/* All Workspaces */}
 93→          <button
 94→            onClick={() => handleSelect(null)}
 95→            className={cn(
 96→              "flex w-full items-center px-3 py-1.5 text-xs transition-colors hover:bg-accent",
 97→              activeWorkspaceId === null && "bg-accent"
 98→            )}
 99→          >
100→            All Workspaces
101→          </button>
102→
103→          {workspaces.length > 0 && <div className="my-1 border-t" />}
104→
105→          {/* Workspace list */}
106→          {workspaces.map((ws) => (
107→            <div
108→              key={ws.id}
109→              className={cn(
110→                "group flex items-center gap-1 px-3 py-1.5 text-xs transition-colors hover:bg-accent cursor-pointer",
111→                activeWorkspaceId === ws.id && "bg-accent"
112→              )}
113→              onClick={() => {
114→                if (renamingId !== ws.id) handleSelect(ws.id);
115→              }}
116→            >
117→              {renamingId === ws.id ? (
118→                <RenameInput
119→                  initialValue={ws.name}
120→                  onConfirm={(name) => {
121→                    onRename(ws.id, name);
122→                    setRenamingId(null);
123→                  }}
124→                  onCancel={() => setRenamingId(null)}
125→                />
126→              ) : (
127→                <>
128→                  <Tip text={ws.name} side="right"><span className="min-w-0 flex-1 truncate">{ws.name}</span></Tip>
129→                  <button
130→                    onClick={(e) => {
131→                      e.stopPropagation();
132→                      setRenamingId(ws.id);
133→                    }}
134→                    className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-accent group-hover:opacity-100"
135→                    aria-label="Rename workspace"
136→                  >
137→                    <Pencil className="size-3 text-muted-foreground" />
138→                  </button>
139→                  <button
140→                    onClick={(e) => {
141→                      e.stopPropagation();
142→                      if (confirm(`Delete workspace "${ws.name}"?`)) {
143→                        onDelete(ws.id);
144→                      }
145→                    }}
146→                    className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-red-500/10 group-hover:opacity-100"
147→                    aria-label="Delete workspace"
148→                  >
149→                    <Trash2 className="size-3 text-red-500" />
150→                  </button>
151→                </>
152→              )}
153→            </div>
154→          ))}
155→
156→          <div className="my-1 border-t" />
157→
158→          {/* Open Folder */}
159→          <button
160→            onClick={() => {
161→              setOpen(false);
162→              onOpenFolder();
163→            }}
164→            className="flex w-full items-center gap-2 px-3 py-1.5 text-xs transition-colors hover:bg-accent"
165→          >
166→            <FolderOpen className="size-3.5 text-muted-foreground" />
167→            Open Folder...
168→          </button>
169→        </div>
170→      )}
171→    </div>
172→  );
173→}
174→
175→/** Inline input for renaming a workspace. */
176→function RenameInput({
177→  initialValue,
178→  onConfirm,
179→  onCancel,
180→}: {
181→  initialValue: string;
182→  onConfirm: (value: string) => void;
183→  onCancel: () => void;
184→}) {
185→  const [value, setValue] = useState(initialValue);
186→  const inputRef = useRef<HTMLInputElement>(null);
187→
188→  useEffect(() => {
189→    inputRef.current?.focus();
190→    inputRef.current?.select();
191→  }, []);
192→
193→  return (
194→    <input
195→      ref={inputRef}
196→      type="text"
197→      value={value}
198→      onChange={(e) => setValue(e.target.value)}
199→      onKeyDown={(e) => {
200→        e.stopPropagation();
201→        if (e.key === "Enter") {
202→          const trimmed = value.trim();
203→          if (trimmed) onConfirm(trimmed);
204→          else onCancel();
205→        } else if (e.key === "Escape") {
206→          onCancel();
207→        }
208→      }}
209→      onBlur={() => {
210→        const trimmed = value.trim();
211→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
212→        else onCancel();
213→      }}
214→      onClick={(e) => e.stopPropagation()}
215→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
216→    />
217→  );
218→}
