331→
332→/** Server sends the full list of agents after every state change. */
333→export interface ServerAgentList {
334→  type: "agent_list";
335→  agents: AgentInfo[];
336→}
337→
338→/** Server confirms a new agent was spawned and assigns its ID. */
339→export interface ServerSpawned {
340→  type: "spawned";
341→  agentId: string;
342→}
343→
344→/** Server sends full message history for an agent (in response to `request_history`). */
345→export interface ServerMessageHistory {
346→  type: "message_history";
347→  agentId: string;
348→  messages: ServerMessage[];
349→}
350→
351→/** CLI WebSocket disconnected (process may have crashed or exited). */
352→export interface ServerCliDisconnected {
353→  type: "cli_disconnected";
354→  agentId: string;
355→}
356→
357→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
358→export interface ServerCliConnected {
359→  type: "cli_connected";
360→  agentId: string;
361→}
362→
363→/** Server confirms message history was cleared for an agent. */
364→export interface ServerHistoryCleared {
365→  type: "history_cleared";
366→  agentId: string;
367→}
368→
369→/** Server sends the full workspace list to the browser. */
370→export interface ServerWorkspaceList {
371→  type: "workspace_list";
372→  workspaces: Workspace[];
373→}
374→
375→/** Server responds with a directory listing for the folder browser. */
376→export interface ServerDirectoryListing {
377→  type: "directory_listing";
378→  path: string;
379→  entries: DirectoryEntry[];
380→}
381→
382→/** Server sends the full task list to the browser. */
383→export interface ServerTaskList {
384→  type: "task_list";
385→  tasks: Task[];
386→}
387→
388→/** Server confirms a task was updated. */
389→export interface ServerTaskUpdated {
390→  type: "task_updated";
391→  task: Task;
392→}
393→
394→/** Server confirms a task was deleted. */
395→export interface ServerTaskDeleted {
396→  type: "task_deleted";
397→  taskId: string;
398→}
399→
400→/** Union of all messages the WS server can send to the browser. */
401→export type ServerMessage =
402→  | ServerRelay
403→  | ServerStatus
404→  | ServerError
405→  | ServerAgentList
406→  | ServerSpawned
407→  | ServerMessageHistory
408→  | ServerCliDisconnected
409→  | ServerCliConnected
410→  | ServerHistoryCleared
411→  | ServerWorkspaceList
412→  | ServerDirectoryListing
413→  | ServerTaskList
414→  | ServerTaskUpdated
415→  | ServerTaskDeleted;
416→
417→// ── UI state ──────────────────────────────────────────────────────────────
418→
419→/**
420→ * Lifecycle states of the Claude agent process:
421→ * - `idle`      — no process running, ready to spawn
422→ * - `spawning`  — process launched, waiting for CLI to connect via WS
423→ * - `connected` — CLI connected and `system/init` received
424→ * - `thinking`  — waiting for assistant response
425→ * - `done`      — `result` message received, process finished
426→ * - `error`     — process crashed or unexpected failure
427→ */
428→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
429→
430→export type ChatMessageRole = "user" | "assistant" | "system";
431→
432→/**
433→ * A single entry in the chat message list. System messages include
434→ * session init info and result summaries. Messages with a `controlRequest`
435→ * are rendered as tool-approval cards instead of plain bubbles.
436→ */
437→/** A single option in an AskUserQuestion question. */
438→export interface UserQuestionOption {
439→  label: string;
440→  description?: string;
441→}
442→
443→/** A single question from AskUserQuestion. */
444→export interface UserQuestion {
445→  question: string;
446→  header?: string;
447→  options: UserQuestionOption[];
448→  multiSelect: boolean;
449→}
450→
451→/** Info about a single tool_use block in an assistant message. */
452→export interface ToolCallInfo {
453→  name: string;
454→  toolUseId?: string;
455→  /** Truncated one-line preview of the tool result, if available. */
456→  resultPreview?: string;
457→  /** Raw tool input data, preserved for file-modifying tools (Edit, Write, MultiEdit). */
458→  input?: Record<string, unknown>;
459→}
460→
461→export interface ChatMessage {
462→  id: string;
463→  role: ChatMessageRole;
464→  content: string;
465→  timestamp: number;
466→  /** Present when this message represents a tool approval request. */
467→  controlRequest?: {
468→    id: string;
469→    tool_name: string;
470→    input: Record<string, unknown>;
471→    /** Tool description from the protocol, if available. */
472→    description?: string;
473→    /** Set to true after the user allows or denies. */
474→    resolved?: boolean;
475→    /** Whether the user allowed (true) or denied (false). */
476→    allowed?: boolean;
477→  };
478→  /** Present when this message is an AskUserQuestion control request. */
479→  userQuestion?: {
480→    requestId: string;
481→    questions: UserQuestion[];
482→    resolved?: boolean;
483→  };
484→  /** Tool calls found in this assistant message. */
485→  toolCalls?: ToolCallInfo[];
486→  /** True when this message has only tool_use/tool_result blocks and no text. */
487→  isToolOnly?: boolean;
488→}
489→
490→// ── Task system ──────────────────────────────────────────────────────────
491→
492→// ── Notifications ──────────────────────────────────────────────────────────
493→
494→export type NotificationType = "done" | "error" | "control_request" | "question";
495→
496→export interface NotificationItem {
497→  id: string;
498→  type: NotificationType;
499→  agentId: string;
500→  agentLabel: string;
501→  message: string;
502→  timestamp: number;
503→  read: boolean;
504→}
505→
506→// ── Tasks ──────────────────────────────────────────────────────────────────
507→
508→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
509→export type TaskPriority = "low" | "medium" | "high" | "urgent";
510→
511→/** A user-created task, optionally linked to a Claude agent. */
512→export interface Task {
513→  id: string;
514→  title: string;
515→  description: string;
516→  status: TaskStatus;
517→  priority: TaskPriority;
518→  /** If delegated, the agentId of the spawned Claude agent. */
519→  agentId: string | null;
520→  /** Workspace this task belongs to. */
521→  workspaceId: string | null;
522→  createdAt: number;
523→  updatedAt: number;
524→}
