 64→  connected: boolean;
 65→  loading?: boolean;
 66→  status: AgentStatus;
 67→  agentLabel?: string | null;
 68→  messages: ChatMessage[];
 69→  rawMessages: ClaudeMessage[];
 70→  activeModel?: string | null;
 71→  selectedModel?: string;
 72→  onModelChange?: (model: string) => void;
 73→  onSendMessage: (content: string) => void;
 74→  onSpawnAgent: (prompt: string, systemPrompt?: string) => void;
 75→  onRespondToControl: (requestId: string, allow: boolean) => void;
 76→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 77→  onClearHistory?: () => void;
 78→  showTasks?: boolean;
 79→  onToggleTasks?: () => void;
 80→  showDiffs?: boolean;
 81→  onToggleDiffs?: () => void;
