198→        onToggleTasks={onToggleTasks}
199→        showDiffs={showDiffs}
200→        onToggleDiffs={onToggleDiffs}
201→        onToggleSidebar={onToggleSidebar}
202→        showWorld={showWorld}
203→        onToggleWorld={onToggleWorld}
204→        onOpenSfxSettings={onOpenSfxSettings}
205→        notificationsEnabled={notificationsEnabled}
206→        onToggleNotifications={onToggleNotifications}
207→        notifications={notifications}
208→        onSelectNotification={onSelectNotification}
209→        onDismissNotification={onDismissNotification}
210→        onClearNotifications={onClearNotifications}
211→        onTestNotification={onTestNotification}
212→      />
213→
214→      <AgentSummary rawMessages={rawMessages} />
215→
216→      <div className="relative flex-1">
217→        {loading ? (
218→          <div className="flex h-full flex-col items-center justify-center gap-3">
219→            <div className="flex gap-1">
220→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
221→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
222→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
223→            </div>
224→            <span className="text-xs text-muted-foreground">
225→              {connected ? "Loading messages..." : "Connecting..."}
226→            </span>
227→          </div>
228→        ) : showRaw ? (
229→          <div className="h-full overflow-y-auto p-2 md:p-4 space-y-1">
230→            {rawMessages.length === 0 ? (
231→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
232→                No raw messages yet
233→              </div>
234→            ) : (
235→              rawMessages.map((msg, i) => (
236→                <RawMessage key={i} message={msg} index={i} />
237→              ))
238→            )}
239→          </div>
