                        if (val) {
                          onModelChange(val);
                          setCustomInput("");
                          setShowCustom(false);
                          setDropdownOpen(false);
                        }
                      }}
                      className="px-2 py-1"
                    >
                      <input
                        ref={customInputRef}
                        type="text"
                        value={customInput}
                        onChange={(e) => setCustomInput(e.target.value)}
                        placeholder="e.g. llama3.3:70b"
                        className="w-full rounded border bg-background px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-ring"
                      />
                    </form>
