                    setInboxOpen(false);
                  }}
                  onDismiss={onDismissNotification}
                  onClear={onClearNotifications}
                  onClose={() => setInboxOpen(false)}
                  onTestPush={onTestNotification}
                />
              )}
            </div>
          )}
          {onToggleWorld && (
