              <TreePine className="size-3.5" />
            </Button>
          )}
          {onOpenSfxSettings && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onOpenSfxSettings}
              title="Sound settings"
            >
              <Volume2 className="size-3.5" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

